import React, { useState, useCallback } from 'react';
import Header from './components/Header';
import ImageUploader from './components/ImageUploader';
import ImageOutput from './components/ImageOutput';
import Footer from './components/Footer';
import ErrorModal from './components/ErrorModal';
import './App.css';

function App() {
  const [uploadedImage, setUploadedImage] = useState(null); // { file, dataUrl }
  const [outputImage, setOutputImage] = useState(null);    // base64 string
  const [isLoading, setIsLoading] = useState(false);
  const [selectedHero, setSelectedHero] = useState(null);
  const [error, setError] = useState(null);

  const handleImageLoaded = useCallback((imageData) => {
    setUploadedImage(imageData);
    setOutputImage(null);
  }, []);

  const handleTransform = useCallback(async () => {
    if (!uploadedImage) {
      setError('Per favore carica un\'immagine prima di procedere.');
      return;
    }
    if (!selectedHero) {
      setError('Per favore seleziona un supereroe prima di procedere.');
      return;
    }

    setIsLoading(true);
    setOutputImage(null);

    try {
      const formData = new FormData();
      formData.append('image', uploadedImage.file);
      formData.append('hero', selectedHero.value);

      const response = await fetch('/api/imagetransformert/v1/transform', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        let errMsg = `Errore dal server: ${response.status}`;
        try {
          const errData = await response.json();
          errMsg = errData.detail || errData.message || errMsg;
        } catch (_) {}
        throw new Error(errMsg);
      }

      const blob = await response.blob();
      const reader = new FileReader();
      reader.onloadend = () => {
        setOutputImage(reader.result);
        setIsLoading(false);
      };
      reader.readAsDataURL(blob);
    } catch (err) {
      setIsLoading(false);
      setError(err.message || 'Si è verificato un errore imprevisto.');
    }
  }, [uploadedImage, selectedHero]);

  const handleReset = useCallback(() => {
    setUploadedImage(null);
    setOutputImage(null);
    setIsLoading(false);
  }, []);

  return (
    <div className="app-layout">
      <Header />

      <main className="app-main">
        <div className="panels-container">
          <ImageUploader
            uploadedImage={uploadedImage}
            onImageLoaded={handleImageLoaded}
          />
          <div className="panels-divider">
            <span className="divider-icon">⚡</span>
          </div>
          <ImageOutput
            outputImage={outputImage}
            isLoading={isLoading}
          />
        </div>
      </main>

      <Footer
        selectedHero={selectedHero}
        onHeroChange={setSelectedHero}
        onTransform={handleTransform}
        onReset={handleReset}
        isLoading={isLoading}
        hasImage={!!uploadedImage}
      />

      {error && (
        <ErrorModal message={error} onClose={() => setError(null)} />
      )}
    </div>
  );
}

export default App;
